CREATE TABLE public.commerce_customer_notifications (id uuid DEFAULT gen_random_uuid() NOT NULL, customer_id uuid NOT NULL, kind text DEFAULT 'shortage'::text NOT NULL, title text NOT NULL, body text NOT NULL, shortage_id uuid, order_id uuid, dedupe_key text, read_at timestamp with time zone, created_at timestamp with time zone DEFAULT now() NOT NULL, product_id uuid);
CREATE TABLE public.commerce_customers (id uuid DEFAULT gen_random_uuid() NOT NULL, external_subject text NOT NULL, phone text, wechat_openid text, wechat_unionid text, nickname text, avatar_url text, status text DEFAULT 'active'::text NOT NULL, last_login_at timestamp with time zone, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.commerce_listings (id uuid DEFAULT gen_random_uuid() NOT NULL, sku_id uuid NOT NULL, location_id uuid NOT NULL, epc text, title text NOT NULL, description text, cover_url text, image_urls jsonb DEFAULT '[]'::jsonb NOT NULL, price numeric(12,2) NOT NULL, compare_at_price numeric(12,2), condition_grade text, category text, status text DEFAULT 'draft'::text NOT NULL, published_at timestamp with time zone, sold_at timestamp with time zone, created_by uuid, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, product_type text DEFAULT 'custom'::text NOT NULL, image_paths jsonb DEFAULT '[]'::jsonb NOT NULL);
CREATE TABLE public.inv_handheld_notifications (id uuid DEFAULT gen_random_uuid() NOT NULL, device_id uuid, location_id uuid, kind text NOT NULL, title text, payload jsonb DEFAULT '{}'::jsonb NOT NULL, ts timestamp with time zone DEFAULT now() NOT NULL, user_id uuid, audience text DEFAULT 'location'::text NOT NULL, action_status text, ref_type text, ref_id uuid, change_xid xid8, change_seq bigint);
CREATE TABLE public.inv_locations (id uuid DEFAULT gen_random_uuid() NOT NULL, kind text NOT NULL, name text NOT NULL, shop_id uuid, is_active boolean DEFAULT true NOT NULL, notes text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.inv_skus (id uuid DEFAULT gen_random_uuid() NOT NULL, category text NOT NULL, price_tier numeric(10,2) NOT NULL, name text NOT NULL, kind text DEFAULT 'single'::text NOT NULL, pack_pieces integer, epc text NOT NULL, weight_g numeric(10,2), image_url text, stock_qty integer DEFAULT 0 NOT NULL, notes text, status text DEFAULT 'active'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, is_custom_price boolean DEFAULT false NOT NULL, sku_code text, bundle_items jsonb DEFAULT '[]'::jsonb NOT NULL, grade text, barcode text, image_paths text[] DEFAULT '{}'::text[] NOT NULL, is_display boolean DEFAULT true NOT NULL, default_shop_ids uuid[] DEFAULT ARRAY[]::uuid[] NOT NULL, sku_scope text DEFAULT 'standard'::text NOT NULL, sales_state text DEFAULT 'active'::text NOT NULL, inventory_version bigint DEFAULT 0 NOT NULL, attributes jsonb DEFAULT '{}'::jsonb NOT NULL, category_source text DEFAULT 'legacy'::text NOT NULL, category_confidence numeric, classification_status text DEFAULT 'legacy'::text NOT NULL, ai_suggested_price numeric(12,2), recognition_request_id uuid, brand_id uuid, brand_candidate_text text, keywords text[] DEFAULT '{}'::text[] NOT NULL, attribute_confidence jsonb DEFAULT '{}'::jsonb NOT NULL, clarification_requests jsonb DEFAULT '[]'::jsonb NOT NULL, sale_ownership text DEFAULT 'owned'::text NOT NULL, discount_eligible boolean DEFAULT true NOT NULL, settlement_party_ref text, inventory_policy text DEFAULT 'tracked'::text NOT NULL, ip_id uuid, ip_candidate_text text, image_processing_status text DEFAULT 'idle'::text NOT NULL, image_processing_updated_at timestamp with time zone, fankuang_override boolean, measurement_height_cm numeric(8,2), measurement_width_cm numeric(8,2), measurement_depth_cm numeric(8,2), measurement_diameter_cm numeric(8,2), measured_by uuid, measured_at timestamp with time zone, measurement_revision integer DEFAULT 0 NOT NULL);
CREATE TABLE public.inv_stocks (sku_id uuid NOT NULL, location_id uuid NOT NULL, qty integer DEFAULT 0 NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.measurement_mutations (id uuid DEFAULT gen_random_uuid() NOT NULL, actor_id uuid NOT NULL, client_op_id text NOT NULL, sku_id uuid NOT NULL, location_id uuid, expected_revision integer NOT NULL, fingerprint jsonb NOT NULL, result jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.product_measurement_assets (sku_id uuid NOT NULL, revision integer NOT NULL, status text DEFAULT 'pending'::text NOT NULL, cutout_preview_path text, bbox jsonb, front_width_px integer, front_height_px integer, px_per_cm numeric(10,3), error text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, verified boolean DEFAULT false NOT NULL, width_cm numeric(8,2), height_cm numeric(8,2));
CREATE TABLE public.product_measurement_requesters (id uuid DEFAULT gen_random_uuid() NOT NULL, task_id uuid NOT NULL, customer_id uuid NOT NULL, notified_at timestamp with time zone, created_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.product_measurement_tasks (id uuid DEFAULT gen_random_uuid() NOT NULL, sku_id uuid NOT NULL, listing_id uuid, location_id uuid, status text DEFAULT 'pending'::text NOT NULL, claimed_by uuid, claimed_at timestamp with time zone, completed_at timestamp with time zone, completed_by uuid, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, client_op_id text);
CREATE TABLE public.user_location_perms (user_id uuid NOT NULL, location_id uuid NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.user_roles (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid NOT NULL, role public.app_role NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL);
