CREATE UNIQUE INDEX inv_skus_pkey ON public.inv_skus USING btree (id);
CREATE UNIQUE INDEX inv_skus_epc_key ON public.inv_skus USING btree (epc);
CREATE UNIQUE INDEX inv_skus_barcode_uidx ON public.inv_skus USING btree (barcode) WHERE (barcode IS NOT NULL);
