CREATE UNIQUE INDEX inv_stocks_pkey ON public.inv_stocks USING btree (sku_id, location_id);
CREATE UNIQUE INDEX measurement_mutations_pkey ON public.measurement_mutations USING btree (id);
CREATE UNIQUE INDEX measurement_mutations_actor_id_client_op_id_key ON public.measurement_mutations USING btree (actor_id, client_op_id);
CREATE UNIQUE INDEX product_measurement_assets_pkey ON public.product_measurement_assets USING btree (sku_id, revision);
CREATE UNIQUE INDEX product_measurement_requesters_pkey ON public.product_measurement_requesters USING btree (id);
CREATE UNIQUE INDEX product_measurement_requesters_task_id_customer_id_key ON public.product_measurement_requesters USING btree (task_id, customer_id);
CREATE UNIQUE INDEX product_measurement_tasks_pkey ON public.product_measurement_tasks USING btree (id);
CREATE UNIQUE INDEX product_measurement_tasks_active_sku ON public.product_measurement_tasks USING btree (sku_id) WHERE (status = ANY (ARRAY['pending'::text, 'claimed'::text]));
CREATE UNIQUE INDEX product_measurement_tasks_client_op ON public.product_measurement_tasks USING btree (client_op_id) WHERE (client_op_id IS NOT NULL);
CREATE UNIQUE INDEX user_location_perms_pkey ON public.user_location_perms USING btree (user_id, location_id);
CREATE UNIQUE INDEX user_roles_pkey ON public.user_roles USING btree (id);
CREATE UNIQUE INDEX user_roles_user_id_role_key ON public.user_roles USING btree (user_id, role);
