ALTER TABLE inv_skus ADD CONSTRAINT inv_skus_sales_state_check CHECK ((sales_state = ANY (ARRAY['draft'::text, 'publishing'::text, 'active'::text, 'sold_syncing'::text, 'sold'::text, 'return_pending'::text, 'return_inspecting'::text, 'retired'::text])));
